head.script:
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    await scwin.gform_onload();
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name ins_search
 * @description 등록번호미등록사유 조회 한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ins_search = async function() {
    if ($c.stf.compareFromToDate2(edt_SDATE, edt_EDATE) === false) {
        return false;
    }

    // alert(getObjectValue(cmb_pISUR_APPL_TP_CD));
    // alert(getObjectValue(cmb_pPROC));

    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};
scwin.arrPar = new Array();

/**
 * @method
 * @name getParam
 * @description 전달값을 설정한다.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParam = function(arrPar) {
    scwin.arrPar[0] = txb_param1.getValue(); // 발행기관코드
    scwin.arrPar[1] = txb_param2.getValue(); // 발행기관코드명

    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    scwin.arrPar, length;
};

/**
 * @method
 * @name gform_onload
 * @description gform onload 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.gform_onload = async function() {
    $c.cm.PanelToGroupBox(panel_1);
    $c.stf.setFromToDate(3, edt_SDATE, edt_EDATE); // 3개월전
    txb_param1.hide();
    txb_param2.hide();
    // edt_SDATE.focus();
    await scwin.ins_search();
};

/**
 * @method
 * @name btn_search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_search_onclick = async function() {
    await scwin.ins_search();
};

/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    await $c.win.alert(dts_List);

};

/**
 * @method
 * @name img_SDATE_onclick
 * @description img_SDATE 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_SDATE_onclick = function() {
    popUpCalendar2(edt_SDATE);
};

/**
 * @method
 * @name img_EDATE_onclick
 * @description img_EDATE 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_EDATE_onclick = function() {
    popUpCalendar2(edt_EDATE);
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = async function(rowcount) {
    // alert('dts_List.OnLoadCompleted('+rowcount+')');
    if (dts_List.errorMsg) {
        await $c.win.alert(dts_List.errorMsg);
    } else {
        txb_TotalCnt.setValue("총 " + rowcount + "건");
    }

};

/**
 * @method
 * @name grd_Grid_OnDblClick
 * @description grd_Grid 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_Grid_OnDblClick = function(row, colid) {
    if (row === 0) return;
    txb_param1.setValue(dts_List.getCellData(row, "ISUR_CD")); // 발행기관코드
    txb_param2.setValue(dts_List.getCellData(row, "ISUR_NM")); // 발행기관명
    fn_GetPar = scwin.getParam;
    ins_popupOpen("", "", "ULDINS91600", "발행기관 상세정보", "1190", "710");
};

/**
 * @method
 * @name cmb_Proc_onselchange
 * @description cmb_Proc onselchange 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.cmb_Proc_onselchange = async function() {
    await scwin.ins_search();
};
